DROP TABLE IF EXISTS gv_vem; CREATE TABLE gv_vem ( survey_year smallint  NULL, code_country smallint  NULL, partner_code smallint  NULL, code_plot integer  NULL, sample_id smallint  NULL, survey_number smallint  NULL, code_species character varying(17)  NULL, code_layer_surface smallint  NULL, code_substrate smallint  NULL, species_cover numeric  NULL, code_certainty smallint  NULL, other_obs character varying  NULL, q_flag smallint  NULL, change_date timestamp without time zone  NULL, code_line character varying(30)  NULL, line_nr integer  NULL);
